const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const V=m=>{console.error('OD12A_VIOLATION: '+m);process.exit(1)};
const H=m=>{console.error('OD12A_HARNESS_ERROR: '+m);process.exit(2)};
try{
 const doc='docs/architecture/OD-12-A-LANTMATERIET-COMPLIANCE-MAPPING-2026-09-27.md';
 const man='docs/architecture/od12a-lm-compliance/SNAPSHOT-MANIFEST.md';
 if(!fs.existsSync(doc)) V('mapping document absent');
 if(!fs.existsSync(man)) V('snapshot manifest absent');
 const d=fs.readFileSync(doc,'utf8');
 const required=['f\u00f6renligt enligt villkorstext','tolkningsfr\u00e5ga','restriktion','OD-12 map state remains **EXTERNAL**','raw_properties','CC0','CC BY 4.0','Licenstagare / juridisk person','Ans\u00f6kningsdatum','Inl\u00e4mnad \u00e4ndam\u00e5lstext','Pr\u00f6vningsstatus','Hydrografi Nedladdning','enskilda firma'];
 for(const x of required) if(!d.includes(x)) V('missing required mapping term: '+x);
 if(/godk\u00e4nt|juridiskt klart/i.test(d)) V('forbidden legal-closure wording present');
 const rows=fs.readFileSync(man,'utf8').split(/\r?\n/).filter(l=>/^\| [^|]+ \| https:\/\//.test(l));
 if(rows.length<8) V('snapshot manifest has fewer than 8 source rows');
 for(const row of rows){
   const c=row.split('|').map(x=>x.trim());
   const name=c[1], expected=c[3];
   if(!/^[A-F0-9]{64}$/.test(expected)) V('invalid manifest hash for '+name);
   const p=path.join('docs/architecture/od12a-lm-compliance/snapshots',name);
   if(!fs.existsSync(p)) V('snapshot missing: '+name);
   const actual=crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex').toUpperCase();
   if(actual!==expected) V('snapshot hash mismatch: '+name);
 }
 console.log('OD12A_MAPPING_BUNDLE_OK');
}catch(e){H(e&&e.stack?e.stack:String(e))}

